  /* ==== SUDOKU PUZZLE BANK: END ==== */

  const FALLBACK_LEVELS = [
    { key: 'easy', label: '简单', level: 1 },
    { key: 'normal', label: '普通', level: 2 },
    { key: 'hard', label: '困难', level: 3 },
    { key: 'expert', label: '专家', level: 4 },
    { key: 'hell', label: '地狱', level: 5 },
  ]

  // The inline bank is the single source of truth for the grade list / labels.
  const LEVELS = (function buildLevels() {
    const source = PUZZLE_BANK && Array.isArray(PUZZLE_BANK.levels) ? PUZZLE_BANK.levels : []
    const levels = []
    for (let i = 0; i < source.length; i++) {
      const level = source[i]
      if (!level || typeof level.key !== 'string' || !level.key) continue
      levels.push({
        key: level.key,
        label: typeof level.label === 'string' && level.label ? level.label : level.key,
        level: typeof level.level === 'number' && isFinite(level.level) ? level.level : i + 1,
      })
    }
    if (levels.length) return levels
    return FALLBACK_LEVELS.map(function clone(level) {
      return { key: level.key, label: level.label, level: level.level }
    })
  })()

  const LEVEL_BY_KEY = Object.create(null)
  for (let i = 0; i < LEVELS.length; i++) LEVEL_BY_KEY[LEVELS[i].key] = LEVELS[i]
  const GRADE_KEYS = LEVELS.map(function key(level) {
    return level.key
  })

  // Cell geometry lookup tables (used by the UI highlight and conflict checks).
  const ROW_OF = new Uint8Array(CELLS)
  const COL_OF = new Uint8Array(CELLS)
  const BOX_OF = new Uint8Array(CELLS)
  for (let i = 0; i < CELLS; i++) {
    const row = (i / GRID) | 0
    const col = i % GRID
    ROW_OF[i] = row
    COL_OF[i] = col
    BOX_OF[i] = ((row / 3) | 0) * 3 + ((col / 3) | 0)
  }

  // ---------------------------------------------------------------------------
  // Small helpers
  // ---------------------------------------------------------------------------

  function isInteger(value) {
    return typeof value === 'number' && isFinite(value) && Math.floor(value) === value
  }

  function isIndex(value) {
    return isInteger(value) && value >= 0 && value < CELLS
  }

  function isDigit(value) {
    return isInteger(value) && value >= 1 && value <= 9
  }

  function zeroGrid() {
    const grid = new Array(CELLS)
    for (let i = 0; i < CELLS; i++) grid[i] = 0
    return grid
  }

  function copyGrid(grid) {
    return grid.slice()
  }

  function normalizeNow(now) {
    return typeof now === 'number' && isFinite(now) ? now : Date.now()
  }

  function countNonZero(grid) {
    let count = 0
    for (let i = 0; i < CELLS; i++) if (grid[i] !== 0) count += 1
    return count
  }

  function isGridOf(value, min, max) {
    if (!Array.isArray(value) || value.length !== CELLS) return false
    for (let i = 0; i < CELLS; i++) {
      const cell = value[i]
      if (!isInteger(cell) || cell < min || cell > max) return false
    }
    return true
  }

  /** Bank givens -> number[81] (0 = empty). Returns null for malformed data. */
  function parseGivens(value) {
    if (typeof value === 'string') {
      if (value.length !== CELLS) return null
      const grid = zeroGrid()
      for (let i = 0; i < CELLS; i++) {
        const code = value.charCodeAt(i)
        if (code < 48 || code > 57) return null
        grid[i] = code - 48
      }
      return grid
    }
    if (Array.isArray(value)) {
      if (!isGridOf(value, 0, 9)) return null
      return value.slice()
    }
    return null
  }

  function normalizeElapsed(value) {
    let ms = Math.round(value)
    if (ms < 0) ms = 0
    if (ms > MAX_ELAPSED_MS) ms = MAX_ELAPSED_MS
    return ms
  }

  function normalizeGrade(grade) {
    if (typeof grade === 'string' && LEVEL_BY_KEY[grade]) return grade
    if (LEVEL_BY_KEY[DEFAULT_GRADE]) return DEFAULT_GRADE
    return LEVELS[0].key
  }

  function gradeLabel(grade) {
    const level = LEVEL_BY_KEY[grade]
    return level ? level.label : String(grade === undefined || grade === null ? '' : grade)
  }

  // ---------------------------------------------------------------------------
  // Seeded RNG — mulberry32 (deterministic pick tests; no puzzle generation)
  // ---------------------------------------------------------------------------

  function createRng(seed) {
    let state = seed >>> 0
    return function next() {
      state = (state + 0x6d2b79f5) >>> 0
      let t = state
      t = Math.imul(t ^ (t >>> 15), t | 1)
      t ^= t + Math.imul(t ^ (t >>> 7), t | 61)
      return ((t ^ (t >>> 14)) >>> 0) / 4294967296
    }
  }

  // ---------------------------------------------------------------------------
  // Inline puzzle bank index / pick (v2 spec §7)
  // ---------------------------------------------------------------------------

  const PUZZLE_BY_ID = new Map()
  const PUZZLES_BY_GRADE = new Map()
  const ALL_PUZZLES = []

  ;(function indexBank() {
    const puzzles = PUZZLE_BANK && Array.isArray(PUZZLE_BANK.puzzles) ? PUZZLE_BANK.puzzles : []
    for (let i = 0; i < puzzles.length; i++) {
      const puzzle = puzzles[i]
      if (!puzzle || typeof puzzle.id !== 'string' || typeof puzzle.givens !== 'string') continue
      if (PUZZLE_BY_ID.has(puzzle.id)) continue
      PUZZLE_BY_ID.set(puzzle.id, puzzle)
      ALL_PUZZLES.push(puzzle)
      const grade = typeof puzzle.grade === 'string' ? puzzle.grade : ''
      if (grade) {
        if (!PUZZLES_BY_GRADE.has(grade)) PUZZLES_BY_GRADE.set(grade, [])
        PUZZLES_BY_GRADE.get(grade).push(puzzle)
      }
    }
  })()

  function findPuzzle(id) {
    if (typeof id !== 'string') return null
    return PUZZLE_BY_ID.get(id) || null
  }

  /**
   * Pick a puzzle for a grade, preferring ids that are not in `played`.
   * When every puzzle of the grade has been played, fall back to the whole
   * grade pool. Does not mutate `played`; returns null only if the bank is empty.
   */
  function pickPuzzle(grade, played, rng) {
    const key = normalizeGrade(grade)
    let pool = PUZZLES_BY_GRADE.get(key) || []
    if (pool.length === 0) pool = ALL_PUZZLES
    if (pool.length === 0) return null
    const playedSet = new Set(Array.isArray(played) ? played : [])
    const unseen = []
    for (let i = 0; i < pool.length; i++) {
      if (!playedSet.has(pool[i].id)) unseen.push(pool[i])
    }
    const candidates = unseen.length ? unseen : pool
    const random = typeof rng === 'function' ? rng : Math.random
    const roll = random()
    const index = Math.min(candidates.length - 1, Math.max(0, Math.floor(roll * candidates.length)))
    return candidates[index]
  }

  /** Filter/dedupe a played-id list (newest last), capped at PLAYED_LIMIT. */
  function trimPlayed(played) {
    if (!Array.isArray(played)) return []
    const seen = new Set()
    const kept = []
    for (let i = played.length - 1; i >= 0; i--) {
      const id = played[i]
      if (typeof id !== 'string' || seen.has(id) || !PUZZLE_BY_ID.has(id)) continue
      seen.add(id)
      kept.push(id)
    }
    kept.reverse()
    return kept.length > PLAYED_LIMIT ? kept.slice(kept.length - PLAYED_LIMIT) : kept
  }

  function markPlayed(played, id) {
    const kept = trimPlayed(played)
    const index = kept.indexOf(id)
    if (index !== -1) kept.splice(index, 1)
    kept.push(id)
    return kept.length > PLAYED_LIMIT ? kept.slice(kept.length - PLAYED_LIMIT) : kept
  }

  // ---------------------------------------------------------------------------
  // Board helpers (v1 spec §4, still apply)
  // ---------------------------------------------------------------------------

  function computeConflicts(board) {
    if (!Array.isArray(board) || board.length !== CELLS) {
      throw new TypeError('sudoku board must be an array of ' + CELLS + ' integers')
    }
    const conflicts = new Array(CELLS)
    for (let i = 0; i < CELLS; i++) conflicts[i] = 0

    for (let i = 0; i < CELLS; i++) {
      const value = board[i]
      if (!value) continue
      const r = ROW_OF[i]
      const c = COL_OF[i]
      let hit = false

      // row
      for (let k = 0; k < GRID; k++) {
        const other = r * GRID + k
        if (other !== i && board[other] === value) {
          hit = true
          break
        }
      }
      // column
      if (!hit) {
        for (let k = 0; k < GRID; k++) {
          const other = k * GRID + c
          if (other !== i && board[other] === value) {
            hit = true
            break
          }
        }
      }
      // box
      if (!hit) {
        const boxRow = ((r / 3) | 0) * 3
        const boxCol = ((c / 3) | 0) * 3
        for (let a = 0; a < 3 && !hit; a++) {
          for (let d = 0; d < 3; d++) {
            const other = (boxRow + a) * GRID + (boxCol + d)
            if (other !== i && board[other] === value) {
              hit = true
              break
            }
          }
        }
      }
      if (hit) conflicts[i] = 1
    }
    return conflicts
  }

  function countEmpty(board) {
    if (!Array.isArray(board)) return CELLS
    let empty = 0
    for (let i = 0; i < CELLS; i++) if (board[i] === 0) empty += 1
    return empty
  }

  function isSolved(board) {
    if (!Array.isArray(board) || board.length !== CELLS) return false
    for (let i = 0; i < CELLS; i++) {
      const value = board[i]
      if (!isInteger(value) || value < 1 || value > 9) return false
    }
    const conflicts = computeConflicts(board)
    for (let i = 0; i < CELLS; i++) if (conflicts[i] !== 0) return false
    return true
  }

  function hasProgress(state) {
    if (!state || !Array.isArray(state.board) || !Array.isArray(state.givens)) return false
    for (let i = 0; i < CELLS; i++) {
      if (state.board[i] !== state.givens[i]) return true
    }
    if (Array.isArray(state.notes)) {
      for (let i = 0; i < CELLS; i++) if (state.notes[i]) return true
    }
    return false
  }

  // ---------------------------------------------------------------------------
  // State machine (spec §4/§5)
  // ---------------------------------------------------------------------------

  function createState(options) {
    const opts = options || {}
    const played = trimPlayed(opts.played)
    const puzzle = pickPuzzle(opts.grade === undefined ? DEFAULT_GRADE : opts.grade, played, opts.rng)
    if (!puzzle) throw new Error('sudoku puzzle bank is empty')
    const givens = parseGivens(puzzle.givens)
    if (!givens) throw new Error('sudoku bank puzzle has malformed givens: ' + puzzle.id)
    const now = normalizeNow(opts.now)
    return {
      puzzleId: puzzle.id,
      grade: puzzle.grade,
      givens: givens,
      board: givens.slice(),
      notes: zeroGrid(),
      selected: null,
      notesMode: false,
      elapsedMs: 0,
      runningSince: now,
      won: false,
      winAcked: false,
      undo: [],
      played: markPlayed(played, puzzle.id),
    }
  }

  function pushUndo(state, entry) {
    state.undo.push(entry)
    if (state.undo.length > UNDO_LIMIT) {
      state.undo.splice(0, state.undo.length - UNDO_LIMIT)
    }
  }

  function selectCell(state, index) {
    if (!state) return false
    if (!isIndex(index)) return false
    state.selected = index
    return true
  }

  function moveSelection(state, dRow, dCol) {
    if (!state) return false
    const deltaRow = isInteger(dRow) ? dRow : 0
    const deltaCol = isInteger(dCol) ? dCol : 0
    const current = state.selected === null || state.selected === undefined ? 0 : state.selected
    const row = Math.min(GRID - 1, Math.max(0, ((current / GRID) | 0) + deltaRow))
    const col = Math.min(GRID - 1, Math.max(0, (current % GRID) + deltaCol))
    const next = row * GRID + col
    if (state.selected !== null && state.selected !== undefined && next === state.selected) return false
    state.selected = next
    return true
  }

  function toggleNotesMode(state) {
    if (!state || state.won) return false
    state.notesMode = !state.notesMode
    return state.notesMode
  }

  function applyDigit(state, index, digit, now) {
    if (!state || state.won) return false
    if (!isIndex(index) || !isDigit(digit)) return false
    if (state.givens[index] !== 0) return false

    if (state.notesMode) {
      if (state.board[index] !== 0) return false
      pushUndo(state, { index: index, prevValue: state.board[index], prevNotes: state.notes[index] })
      state.notes[index] = state.notes[index] ^ (1 << (digit - 1))
      return true
    }

    if (state.board[index] === digit) return false
    pushUndo(state, { index: index, prevValue: state.board[index], prevNotes: state.notes[index] })
    state.board[index] = digit
    state.notes[index] = 0
    if (isSolved(state.board)) {
      state.won = true
      state.winAcked = false
      timerPause(state, normalizeNow(now))
    }
    return true
  }

  function eraseCell(state, index, now) {
    if (!state || state.won) return false
    if (!isIndex(index)) return false
    if (state.givens[index] !== 0) return false
    if (state.board[index] === 0 && state.notes[index] === 0) return false
    pushUndo(state, { index: index, prevValue: state.board[index], prevNotes: state.notes[index] })
    state.board[index] = 0
    state.notes[index] = 0
    return true
  }

  function undoMove(state, now) {
    if (!state || state.won) return false
    if (!Array.isArray(state.undo) || state.undo.length === 0) return false
    while (state.undo.length > 0) {
      const entry = state.undo.pop()
      if (!entry || typeof entry !== 'object') continue
      const index = entry.index
      if (!isIndex(index)) continue
      if (!Array.isArray(state.givens) || state.givens[index] !== 0) continue
      const prevValue = isInteger(entry.prevValue) && entry.prevValue >= 0 && entry.prevValue <= 9
        ? entry.prevValue
        : 0
      const prevNotes = isInteger(entry.prevNotes) && entry.prevNotes >= 0 && entry.prevNotes <= 511
        ? entry.prevNotes
        : 0
      state.board[index] = prevValue
      state.notes[index] = prevNotes
      return true
    }
    return false
  }

  function restartPuzzle(state, now) {
    if (!state) return
    state.board = state.givens.slice()
    state.notes = zeroGrid()
    state.undo = []
    state.elapsedMs = 0
    state.runningSince = normalizeNow(now)
    state.won = false
    state.winAcked = false
    if (state.selected !== null && state.selected !== undefined && !isIndex(state.selected)) {
      state.selected = null
    }
  }

  function newPuzzle(state, grade, rng, now) {
    if (!state) return
    const played = trimPlayed(state.played)
    const puzzle = pickPuzzle(grade, played, rng)
    if (!puzzle) return
    const givens = parseGivens(puzzle.givens)
    if (!givens) return
    state.puzzleId = puzzle.id
    state.grade = puzzle.grade
    state.givens = givens
    state.board = givens.slice()
    state.notes = zeroGrid()
    state.selected = null
    state.elapsedMs = 0
    state.runningSince = normalizeNow(now)
    state.won = false
    state.winAcked = false
    state.undo = []
    state.played = markPlayed(played, puzzle.id)
  }

  // ---------------------------------------------------------------------------
  // Timer (spec §4)
  // ---------------------------------------------------------------------------

  function timerResume(state, now) {
    if (!state) return
    if (state.runningSince === null || state.runningSince === undefined) {
      state.runningSince = normalizeNow(now)
    }
  }

  function timerPause(state, now) {
    if (!state) return
    if (state.runningSince === null || state.runningSince === undefined) return
    const at = normalizeNow(now)
    const elapsed = at - state.runningSince
    state.elapsedMs += elapsed > 0 ? elapsed : 0
    state.runningSince = null
  }

  function timerElapsed(state, now) {
    if (!state) return 0
    const base = isInteger(state.elapsedMs) && state.elapsedMs > 0 ? state.elapsedMs : 0
    if (state.runningSince === null || state.runningSince === undefined) return base
    const at = normalizeNow(now)
    const delta = at - state.runningSince
    return base + (delta > 0 ? delta : 0)
  }

  // ---------------------------------------------------------------------------
  // Save / restore (spec §6)
  // ---------------------------------------------------------------------------

  function getStorage() {
    try {
      if (typeof window === 'undefined' || !window) return null
      const storage = window.localStorage
      if (!storage) return null
      if (typeof storage.getItem !== 'function' || typeof storage.setItem !== 'function') return null
      return storage
    } catch (error) {
      return null
    }
  }

  /** Player layer: 0 on given cells, the player's digit elsewhere. */
